package server

// themeBoot resolves the theme before the first paint. It is served from
// /theme.js and loaded render-blocking in the head: the page's CSP allows
// script-src 'self' only, so it cannot be inlined, and deferring it would let
// a reviewer who has pinned a theme against their OS preference see the other
// one flash first. Storage is optional: a reviewer with it blocked still gets
// the OS preference and a toggle that works for the life of the page.
const themeBoot = `(()=>{const r=document.documentElement,k='change-saga-theme';
let stored=null;try{stored=localStorage.getItem(k)}catch{}
if(stored==='dark'||stored==='light')r.dataset.theme=stored;
const dark=()=>r.dataset.theme?r.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;
const sync=b=>{if(b){b.setAttribute('aria-pressed',String(dark()));b.title=dark()?'Switch to light mode':'Switch to dark mode'}};
addEventListener('DOMContentLoaded',()=>sync(document.querySelector('[data-theme-toggle]')));
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-theme-toggle]');if(!b)return;
const next=dark()?'light':'dark';r.dataset.theme=next;try{localStorage.setItem(k,next)}catch{}sync(b)})})()`

// pageTemplate renders the whole reviewer surface. Chrome text stays in the
// reviewer's vocabulary: chapters, files, changes, comments. Storage and format
// vocabulary (fragments, sections, media types, schema versions, manifests)
// belongs to the CLI and the validator, not to this page. Authored saga content
// is rendered verbatim and may of course discuss the format itself.
var pageTemplate = storyLinksTemplate + `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{.Saga.Manifest.Title}} · Change Saga</title>
<style>` + pageStyles + reviewStyles + `</style><script src="/theme.js"></script><script src="/app.js" defer></script></head><body data-saga-id="{{.Saga.Manifest.ID}}">` + iconSprite + `
<header class="topbar"><div class="brand">{{template "icon" "book"}}<span>change-saga</span></div><span class="opening-badge {{if .Comparing}}compare{{else}}observe{{end}}" data-opening="{{if .Comparing}}compare{{else}}observe{{end}}" title="{{if .Comparing}}The living Saga is read-only here; approvals happen in the pull request's review{{else}}Observing the app at one commit{{end}}">{{.Opening}}</span><nav class="side-tabs" aria-label="Sides"><a class="side-tab{{if not .ReviewSide}} current{{end}}" href="/" data-side="documentation"{{if not .ReviewSide}} aria-current="page"{{end}} title="What the app is and what it does: the overview and the feature set">{{template "icon" "list"}}Documentation</a><a class="side-tab{{if .ReviewSide}} current{{end}}" href="/reviews" data-side="review"{{if .ReviewSide}} aria-current="page"{{end}} title="What is being changed about it: the current and completed reviews">{{template "icon" "diff"}}Review</a></nav>{{if .ReviewSide}}<div class="view-tabs" role="tablist" aria-label="Review"><button type="button" role="tab" id="view-tab-saga" class="view-tab active" data-view-tab="saga" aria-controls="view-saga" aria-selected="true" tabindex="0" title="The review deck: what the change did and why">{{template "icon" "list"}}{{.DeckLabel}}</button>{{if .Comparing}}<button type="button" role="tab" id="view-tab-change" class="view-tab" data-view-tab="change" aria-controls="view-change" aria-selected="false" tabindex="-1" title="What this change edited, what it affected, and its code">{{template "icon" "split"}}Change</button>{{end}}{{if .ReviewCodeHref}}<button type="button" role="tab" id="view-tab-code" class="view-tab" data-view-tab="code" aria-controls="view-code" aria-selected="false" tabindex="-1" title="Every changed line of the change under review">{{template "icon" "diff"}}Code Diff</button>{{end}}{{if .ReviewCoverageHref}}<button type="button" role="tab" id="view-tab-manifest" class="view-tab" data-view-tab="manifest" aria-controls="view-manifest" aria-selected="false" tabindex="-1" title="How completely the deck explains the change">{{template "icon" "check"}}Coverage</button>{{end}}</div>{{else}}<div class="view-tabs" role="tablist" aria-label="Documentation"><button type="button" role="tab" id="view-tab-saga" class="view-tab active" data-view-tab="saga" aria-controls="view-saga" aria-selected="true" tabindex="0" title="Read the living documentation">{{template "icon" "list"}}Saga</button><button type="button" role="tab" id="view-tab-manifest" class="view-tab" data-view-tab="manifest" aria-controls="view-manifest" aria-selected="false" tabindex="-1" title="Which code each record explains, resolved at the head">{{template "icon" "check"}}Documented code</button></div>{{end}}{{if .EmbeddedDecks}}<button type="button" class="view-tab slide-present" data-slide-present aria-pressed="false" title="Present the current slide fullscreen">Present</button>{{end}}<div class="top-meta" data-code-meta hidden></div><button type="button" class="icon-button theme-toggle" data-theme-toggle aria-pressed="false" aria-label="Toggle dark mode" title="Switch to dark mode">{{template "icon" "half"}}</button></header>
<div class="shell" data-shell><aside class="sidebar" id="changed-files-panel"><a class="sidebar-title" href="/">{{template "icon" "book"}}<span>{{.Saga.Manifest.Title}}</span></a><div class="saga-side"><nav class="doc-tree" aria-label="Contents">{{template "doc-tree" .Nav}}</nav></div><div class="code-side" data-code-sidebar hidden><div class="surface-placeholder compact" role="status" aria-live="polite"><span class="surface-spinner" aria-hidden="true"></span><span>Changed files load when Code Diff opens.</span></div></div></aside>
<main class="content"><div class="view active" id="view-saga" role="tabpanel" aria-labelledby="view-tab-saga" data-view="saga">{{if .Error}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Error}}</span></div>{{else if .Diagnostic}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Diagnostic}}</span></div>{{end}}{{if .RequirementsMode}}{{template "requirements-page" .Requirements}}{{else if .TermsMode}}{{template "terms-page" .Terms}}{{else if .Persona}}{{template "persona-page" .Persona}}{{else if .Feature}}{{template "feature-page" .Feature}}{{else if .Features}}{{template "directory-page" .Features}}{{else if .Personas}}{{template "directory-page" .Personas}}{{else if .Flags}}{{template "directory-page" .Flags}}{{else if .DesignSystemMode}}{{template "design-system-page" .}}{{else if .TestCase}}{{template "test-case-page" .TestCase}}{{else if .Reviews}}{{.Reviews}}{{else}}<header class="page-heading"><h1>{{.Saga.Manifest.Title}}</h1>{{with .CoverageTotals}}{{template "coverage-totals" .}}{{else}}<p class="coverage-totals loading" data-coverage-loading data-totals-href="/api/totals" role="status">{{if .Comparing}}Building the review index… Coverage will update when it is ready.{{else}}Reading the documented code…{{end}}</p>{{end}}</header>{{template "overview" .Root}}{{template "overview-directory" .OverviewParts}}{{if .Root.ChildViews}}<section class="chapter-index"><h2>Chapters</h2>{{template "chapter-list" .Root}}</section>{{end}}{{end}}</div>
{{if .EmbeddedDecks}}<div class="view" id="view-slides" role="tabpanel" aria-labelledby="view-tab-saga" data-view="slides"><div class="sidebar-slide-surface">{{template "deck-viewer" .SlideRoot}}</div></div>{{end}}
{{if .ReviewCodeHref}}<div class="view" id="view-code" role="tabpanel" aria-labelledby="view-tab-code" data-view="code" data-review-surface="code" data-surface-href="{{.ReviewCodeHref}}"><div class="surface-placeholder" role="status" aria-live="polite" data-surface-status><span class="surface-spinner" aria-hidden="true"></span><strong>Code Diff is ready when you open it.</strong><span>The comparison stays out of the initial page.</span></div></div>{{end}}</main></div>
{{if and .Comparing .ReviewSide}}<main class="change-view view" id="view-change" role="tabpanel" aria-labelledby="view-tab-change" data-view="change" data-review-surface="change" data-surface-href="/api/change"><div class="surface-placeholder" role="status" aria-live="polite" data-surface-status><span class="surface-spinner" aria-hidden="true"></span><strong>The change loads when you open it.</strong><span>Changed, Affected, and Code appear together.</span></div></main>{{end}}{{if or .ReviewCoverageHref (not .ReviewSide)}}<main class="manifest-view view" id="view-manifest" role="tabpanel" aria-labelledby="view-tab-manifest" data-view="manifest" data-review-surface="manifest" data-surface-href="{{if .ReviewSide}}{{.ReviewCoverageHref}}{{else}}/api/coverage?scope=documented{{end}}"><div class="surface-placeholder" role="status" aria-live="polite" data-surface-status><span class="surface-spinner" aria-hidden="true"></span><strong>{{if .ReviewSide}}Coverage{{else}}Documented code{{end}} loads when you open it.</strong><span>Files appear automatically as they are ready.</span></div></main>{{end}}
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" id="review-drawer" aria-hidden="true" inert aria-label="Linked code"><div class="drawer-head">{{template "icon" "diff"}}<strong id="review-drawer-title">Linked code</strong><button type="button" class="icon-button" data-close-drawer aria-label="Close linked code" title="Close">{{template "icon" "close"}}</button></div><div class="drawer-body"></div></aside>
</body></html>{{end}}

{{define "icon"}}<svg class="i" aria-hidden="true" focusable="false"><use href="#i-{{.}}"></use></svg>{{end}}
{{define "ficon"}}<svg class="ficon" aria-hidden="true" focusable="false"><use href="#{{fileIcon .}}"></use></svg>{{end}}

{{define "slide-mini-media"}}{{if eq .MediaType "text/html"}}<iframe tabindex="-1" sandbox="allow-scripts" loading="lazy" src="{{.URL}}" title=""></iframe>{{else}}<img loading="lazy" src="{{.URL}}" alt="">{{end}}{{end}}
{{define "slide-reference"}}<a class="related-slide" href="{{.Href}}" data-open-fragment="{{.Anchor}}" aria-label="Open slide: {{.Title}}"><span class="related-slide-preview" aria-hidden="true">{{template "slide-mini-media" .}}</span><span class="related-slide-caption"><strong>{{.Title}}</strong></span>{{if .ItemCount}}<small>{{.ItemCount}} linked {{if eq .ItemCount 1}}item{{else}}items{{end}}</small>{{end}}</a>{{end}}
{{define "related-saga-groups"}}{{range .}}<section class="related-chapter{{if .Deck}} related-deck{{end}}">{{if .Deck}}<h3 class="related-chapter-link">{{.Title}}</h3>{{else}}<a class="related-chapter-link" href="{{.Href}}">{{.Title}}</a>{{end}}<div class="related-group-items">{{range .Fragments}}{{if .Slide}}{{template "slide-reference" .Slide}}{{else}}<a class="related-fragment" href="{{.Href}}" data-open-fragment="{{.Anchor}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}{{end}}</div></section>{{end}}{{end}}
{{define "manifest-owner-reference"}}{{if .Href}}<a href="{{.Href}}"{{if .Slide}} class="manifest-slide-owner"{{end}}>{{if .Slide}}<span class="manifest-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Slide}}</span><span class="manifest-slide-copy"><strong>{{.Slide.Title}}</strong><small>{{if ne .Title .Slide.Title}}{{.Title}}{{if .Chapter}} · {{end}}{{end}}{{.Chapter}}</small></span>{{else}}{{template "icon" "book"}}<strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}{{end}}</a>{{else}}<span class="manifest-owner-missing">{{.Title}}</span>{{end}}{{end}}

{{define "code-view"}}<div data-review-surface-response="code"><div data-code-sidebar-content><div class="tree-tools"><label class="tree-search">{{template "icon" "search"}}<input type="search" data-file-filter placeholder="Filter files" aria-label="Filter changed files"></label><button type="button" class="icon-button" data-toggle-tree aria-label="Hide file tree" title="Hide file tree">{{template "icon" "panel-left"}}</button></div><p class="tree-summary" data-tree-summary>{{.Tree.FileCount}} {{if eq .Tree.FileCount 1}}file{{else}}files{{end}} · {{template "diff-counts" .Tree}}</p><div class="file-tree" role="tree" aria-label="Changed files" data-page-items="files">{{template "file-tree-nodes" .Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p></div><div data-code-panel-content><span data-code-meta-content hidden>{{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}}</span><div class="code-toolbar" role="toolbar" aria-label="Code review layout"><button type="button" class="icon-button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true" aria-label="Toggle file tree" title="File tree">{{template "icon" "panel-left"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-layout="inline" aria-pressed="true" aria-label="Unified diff" title="Unified">{{template "icon" "inline"}}</button><button type="button" class="icon-button" data-layout="split" aria-pressed="false" aria-label="Side-by-side diff" title="Side by side">{{template "icon" "split"}}</button><span class="spacer"></span><span class="metric">{{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}}</span><button type="button" class="icon-button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true" aria-label="Toggle explanations panel" title="Explained by">{{template "icon" "panel-right"}}</button></div><div class="code-workspace" data-code-workspace><div class="code-main">{{if .SelectedFile}}{{template "file-diff-shell" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .SelectedFile}}<aside class="related-saga" id="related-saga-panel" aria-label="Explanations for this file"><div class="related-head"><h2>Explained by</h2><button type="button" class="icon-button" data-toggle-related aria-label="Hide explanations panel" title="Hide">{{template "icon" "close"}}</button></div>{{if .RelatedSaga}}{{template "related-saga-groups" .RelatedSaga}}{{else}}<p>{{.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></div>{{end}}

{{define "review-file-diff-surface"}}<div class="diff-surface" data-diff-surface data-layout="inline" data-file-path="{{.Path}}"><div class="review-file-diff-actions"><span data-file-diff-status role="status">Loading every changed hunk…</span>{{with .CodeHref}}<a href="{{.}}">Open in Code Diff{{template "icon" "arrow-right"}}</a>{{end}}</div><div class="diff-column-head" aria-hidden="true"><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines" data-file-diff-rows data-diff-body data-page-items="lines"><p class="diff-placeholder" data-diff-placeholder>Loading changed hunks…</p></div></div>{{end}}

{{define "file-diff-shell"}}{{with .SelectedFile}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}" data-file-diff-href="/api/file-diff?file={{urlquery .Path}}{{with $.SelectedRef}}&amp;ref={{urlquery .}}{{end}}"><header class="file-head">{{template "ficon" .Path}}<code>{{.Path}}</code><span class="counts">{{template "diff-counts" .}}</span></header>{{template "review-file-diff-surface" (reviewDiffSurface .Path "")}}</article>{{end}}{{end}}

{{define "manifest-view"}}<div data-review-surface-response="manifest"><div class="manifest-wrap">
<div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="true">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="false">Saga → Code</button></div><span class="manifest-metric">{{len .Files}} files · {{.Total}} changes</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
{{if .Uncovered}}<div class="manifest-alert" role="alert">{{template "icon" "alert"}}<span><strong>{{.Uncovered}} {{if eq .Uncovered 1}}change is{{else}}changes are{{end}} missing from the story.</strong>Open the highlighted files below and explain them before review can complete.</span></div>{{end}}
<section class="manifest-panel" data-manifest-panel="code">{{if .Tree}}<div class="mtree">{{template "manifest-tree-nodes" .Tree}}</div>{{else}}<div class="manifest-empty">No source changes in this comparison.</div>{{end}}<p class="manifest-filter-empty" data-manifest-empty hidden>No files match this filter.</p></section>
<section class="manifest-panel" data-manifest-panel="saga" hidden><div class="mtree">{{range .Targets}}{{template "manifest-target" .}}{{else}}<div class="manifest-empty">Nothing in the story maps to source changes yet.</div>{{end}}</div><p class="manifest-filter-empty" data-manifest-empty hidden>Nothing matches this filter.</p></section>
{{if .Orphans}}<section class="manifest-orphans"><h2>Stale references</h2><p>These committed references no longer match the current comparison.</p>{{range .Orphans}}<div class="manifest-orphan">{{template "icon" "alert"}}<div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open</a>{{end}}</div>{{end}}</section>{{end}}</div></div>{{end}}

{{define "manifest-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details class="manifest-folder" data-manifest-folder open style="--depth:{{.Depth}}"><summary>{{template "twisty"}}{{template "icon" "folder"}}<span class="mfile-name">{{.Name}}</span><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div>{{template "manifest-tree-nodes" .Children}}</div></details>{{else}}{{template "manifest-file" .}}{{end}}{{end}}{{end}}

{{define "manifest-file"}}{{with .File}}<details class="manifest-file {{if .Uncovered}}has-gap{{end}}" data-manifest-search="{{.Path}}" style="--depth:{{$.Depth}}"><summary>{{template "twisty"}}{{template "ficon" .Path}}<span class="mfile-name">{{$.Name}}</span><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} file {{if eq .Events 1}}event{{else}}events{{end}}{{end}}{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div class="manifest-file-detail" style="--depth:{{$.Depth}}">{{if .HasDiff}}{{template "manifest-diff-surface" .Path}}{{end}}<div class="manifest-map-heading">Explained by</div><div class="manifest-rows">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></div></details>{{end}}{{end}}

{{define "twisty"}}<svg class="i twisty" aria-hidden="true" focusable="false"><use href="#i-chevron"></use></svg>{{end}}

{{define "manifest-code-chunk"}}<div class="manifest-row {{if not .Covered}}unmapped{{end}}"><a class="manifest-range" href="{{.Href}}"><span>{{.Label}}</span><small>{{.AtomCount}} {{if eq .AtomCount 1}}changed line{{else}}changed lines{{end}}</small></a><div class="manifest-owners">{{range .Owners}}{{template "manifest-owner-reference" .}}{{else}}<span class="manifest-gap">Not explained yet</span>{{end}}</div></div>{{end}}

{{define "manifest-diff-surface"}}<div class="manifest-file-diff diff-surface" data-diff-surface data-layout="inline" data-file-path="{{.}}" data-manifest-diff-href="/api/file-diff?view=manifest&amp;file={{urlquery .}}" aria-label="Diff for {{.}}"><div class="diff-lines" data-manifest-diff-rows><p class="diff-placeholder" data-diff-placeholder>Loading the file diff…</p></div></div>{{end}}

{{define "manifest-file-diff-context"}}{{range .Lines}}{{template "manifest-diff-row" .}}{{end}}{{end}}
{{define "manifest-file-diff-page"}}<div data-file-diff-page data-file-path="{{.File.Path}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="lines">{{template "manifest-file-diff-context" .File}}</div></div>{{end}}
{{define "file-diff-page"}}<div data-file-diff-page data-file-path="{{.File.Path}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="lines">{{range .File.Lines}}{{template "diff-surface-row" .}}{{end}}</div></div>{{end}}

{{define "coverage-totals"}}<p class="coverage-totals" data-coverage-totals>{{.Files}} {{if eq .Files 1}}file{{else}}files{{end}} · {{.Total}} changed {{if eq .Total 1}}line{{else}}lines{{end}} · {{.Covered}} explained{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</p>{{end}}
{{define "observe-totals"}}<p class="coverage-totals" data-coverage-totals data-observe-totals>{{len .Targets}} {{if eq (len .Targets) 1}}record references{{else}}records reference{{end}} code · {{.References}} {{if eq .References 1}}range{{else}}ranges{{end}} in {{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}}{{if .Stale}} · <span class="gap">{{.Stale}} stale</span>{{end}}</p>{{end}}
{{define "reference-code"}}<div data-reference-code>{{range .}}<figure class="term-code{{if .Stale}} stale{{end}}" data-file-path="{{.Path}}"><figcaption>{{template "ficon" .Path}}<code>{{.Location}}</code></figcaption>{{if .Note}}<p class="term-code-note" role="note">{{.Note}}</p>{{end}}<table class="term-code-lines"><tbody>{{range .Lines}}<tr{{if .Referenced}} class="referenced"{{end}}><th scope="row">{{.Number}}</th><td><code data-code>{{.Text}}</code></td></tr>{{end}}</tbody></table></figure>{{end}}</div>{{end}}
{{define "observe-coverage-page"}}
<section data-review-surface-response="manifest" data-page-key="coverage" data-coverage-page data-observe-coverage data-mode="{{.Mode}}" data-references="{{.References}}" data-stale="{{.Stale}}">
  <div class="manifest-wrap">
    <div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="{{if eq .Mode "code"}}true{{else}}false{{end}}">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="{{if eq .Mode "saga"}}true{{else}}false{{end}}">Saga → Code</button></div><span class="manifest-metric">{{len .Targets}} {{if eq (len .Targets) 1}}record{{else}}records{{end}} · {{.References}} {{if eq .References 1}}range{{else}}ranges{{end}} · {{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}}{{if .Stale}} · <span class="gap">{{.Stale}} stale</span>{{end}}</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
    <p class="observe-coverage-note">Observing one commit: the code this Saga documents, resolved at the head. Code no record references is not listed; ownership grows as changes land.</p>
    <section class="manifest-panel" data-manifest-panel="{{.Mode}}"><div class="mtree">
      {{if eq .Mode "code"}}{{range .Files}}<details class="manifest-page-row manifest-file{{if .Stale}} has-gap{{end}}" data-manifest-search="{{.Path}}" data-observe-file="{{.Path}}"><summary>{{template "twisty"}}{{template "ficon" .Path}}<span class="mfile-name">{{.Path}}</span><span class="manifest-file-stats">{{.Ranges}} {{if eq .Ranges 1}}range{{else}}ranges{{end}} · {{.Targets}} {{if eq .Targets 1}}record{{else}}records{{end}}{{if .Stale}} · <span class="gap">{{.Stale}} stale</span>{{end}}</span></summary><div class="manifest-file-detail"><ul class="trace-links">{{range .Owners}}<li>{{if .Href}}<a href="{{.Href}}">{{.Title}}</a>{{else}}{{.Title}}{{end}} <small class="trace-kind">{{.Kind}}</small> <small class="trace-note"><code>{{.Location}}</code>{{if .Stale}} · stale{{end}}</small></li>{{end}}</ul></div></details>
      {{else}}<p class="observe-coverage-empty">No record references code yet.</p>{{end}}{{else}}{{range .Targets}}<details class="manifest-page-row manifest-target{{if .Stale}} has-gap{{end}}" data-manifest-search="{{.Title}} {{.Kind}}" data-observe-target="{{.Target}}" data-lazy-href="{{.CodeHref}}"><summary>{{template "twisty"}}{{template "icon" "book"}}<span class="manifest-target-title"><strong>{{.Title}}</strong><small>{{.Kind}}{{if .Note}} · {{.Note}}{{end}}</small></span><span class="manifest-file-stats">{{len .References}} {{if eq (len .References) 1}}range{{else}}ranges{{end}}{{if .Stale}} · <span class="gap">{{.Stale}} stale</span>{{end}}</span></summary><div class="manifest-target-files"><ul class="observe-references">{{range .References}}<li{{if .Stale}} class="stale"{{end}}>{{template "ficon" .Path}}<code>{{.Location}}</code>{{if .Stale}} <span class="gap">stale: {{.Reason}}</span>{{end}}</li>{{end}}</ul><div data-lazy-body><p class="diff-placeholder">The code loads when opened.</p></div>{{if .Href}}<a class="manifest-open-saga" href="{{.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a>{{end}}</div></details>
      {{else}}<p class="observe-coverage-empty">No record references code yet. Items explain code once <code>change-saga cover</code> references it.</p>{{end}}{{end}}
    </div></section>
  </div>
</section>
{{end}}
{{define "coverage-page"}}
<section data-review-surface-response="manifest" data-review-surface-page data-page-key="coverage" data-coverage-page data-mode="{{.Mode}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}" data-total="{{.Summary.Total}}" data-covered="{{.Summary.Covered}}" data-uncovered="{{.Summary.Uncovered}}" data-overlapping="{{.Summary.Overlapping}}" data-orphaned="{{.Summary.Orphaned}}" data-complete="{{.Summary.Complete}}">
  <div class="manifest-wrap">
    <div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="{{if eq .Mode "code"}}true{{else}}false{{end}}">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="{{if eq .Mode "saga"}}true{{else}}false{{end}}">Saga → Code</button></div><span class="manifest-metric">{{.Summary.Files}} files · {{.Summary.Total}} changes</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
    <section class="manifest-panel" data-manifest-panel="{{.Mode}}"><div data-page-items="coverage">
      {{if eq .Mode "code"}}<div class="mtree">{{range .Code}}
        <details class="manifest-page-row manifest-file {{if .File.Uncovered}}has-gap{{end}}" data-manifest-search="{{.File.Path}}" data-coverage-file-href="/api/coverage-file?file={{urlquery .File.Path}}"><summary>{{template "twisty"}}{{template "ficon" .File.Path}}<span class="mfile-name">{{.File.Path}}</span><span class="manifest-file-stats">{{template "diff-counts" .File}}{{if .File.Uncovered}} · <span class="gap">{{.File.Uncovered}} unexplained</span>{{end}}</span></summary><div class="manifest-file-detail">{{template "manifest-diff-surface" .File.Path}}<div class="manifest-map-heading">Explained by</div><div data-coverage-file-mappings><p class="diff-placeholder">Coverage details load when opened.</p></div></div></details>
      {{end}}</div>{{else}}<div class="mtree">{{range .Saga}}
        <details class="manifest-page-row manifest-target" data-manifest-search="{{.Target.Title}} {{.Target.Chapter}}" data-coverage-target-href="/api/coverage-target?target={{urlquery .Target.Target}}"><summary>{{template "twisty"}}{{if .Target.Slide}}<span class="manifest-target-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Target.Slide}}</span>{{else}}{{template "icon" "book"}}{{end}}<span class="manifest-target-title"><strong>{{if .Target.Slide}}{{.Target.Slide.Title}}{{else}}{{.Target.Title}}{{end}}</strong>{{if .Target.Slide}}<small>{{if ne .Target.Title .Target.Slide.Title}}{{.Target.Title}}{{if .Target.Chapter}} · {{end}}{{end}}{{.Target.Chapter}}</small>{{else if .Target.Chapter}}<small>{{.Target.Chapter}}</small>{{end}}</span><span class="manifest-file-stats">{{.AtomCount}} {{if eq .AtomCount 1}}change{{else}}changes{{end}} · {{.FileCount}} {{if eq .FileCount 1}}file{{else}}files{{end}}</span></summary><div class="manifest-target-files"><div data-coverage-target-files><p class="diff-placeholder">Linked files load when opened.</p></div><a class="manifest-open-saga" href="{{.Target.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a></div></details>
      {{end}}</div>{{if .Orphans}}<section class="manifest-orphans"><h2>Stale references</h2>{{range .Orphans}}<div class="manifest-orphan">{{template "icon" "alert"}}<div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open</a>{{end}}</div>{{end}}</section>{{end}}{{end}}
    </div></section>
  </div>
</section>
{{end}}

{{define "coverage-file-page"}}<div data-coverage-file-response data-file="{{.File}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="coverage-file">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></div>{{end}}
{{define "coverage-target-page"}}<div data-coverage-target-response data-target="{{.Target}}" data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}"><div data-page-items="target-files">{{range .Files}}{{template "manifest-target-file" .}}{{end}}</div></div>{{end}}

{{define "code-page"}}<section data-review-surface-response="code" data-review-surface-page data-page-key="files" data-code-page data-next-cursor="{{.NextCursor}}" data-has-more="{{.HasMore}}" data-returned="{{.Returned}}" data-total-files="{{.TotalFiles}}"{{with .Selected}} data-file-path="{{.Path}}"{{end}}><div data-code-sidebar-content><div class="tree-tools"><label class="tree-search">{{template "icon" "search"}}<input type="search" data-file-filter placeholder="Filter files" aria-label="Filter changed files"></label><button type="button" class="icon-button" data-toggle-tree aria-label="Hide file tree" title="Hide file tree">{{template "icon" "panel-left"}}</button></div><p class="tree-summary" data-tree-summary>{{.TotalFiles}} {{if eq .TotalFiles 1}}file{{else}}files{{end}}</p><div class="file-tree" role="tree" aria-label="Changed files" data-page-items="files">{{template "file-tree-nodes" .Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p></div><div data-code-panel-content><span data-code-meta-content hidden>{{.TotalFiles}} {{if eq .TotalFiles 1}}file{{else}}files{{end}}</span><div class="code-toolbar" role="toolbar" aria-label="Code review layout"><button type="button" class="icon-button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true" aria-label="Toggle file tree" title="File tree">{{template "icon" "panel-left"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-layout="inline" aria-pressed="true" aria-label="Unified diff" title="Unified">{{template "icon" "inline"}}</button><button type="button" class="icon-button" data-layout="split" aria-pressed="false" aria-label="Side-by-side diff" title="Side by side">{{template "icon" "split"}}</button><span class="spacer"></span><span class="metric">{{.TotalFiles}} {{if eq .TotalFiles 1}}file{{else}}files{{end}}</span>{{if .Explanations}}<button type="button" class="icon-button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true" aria-label="Toggle explanations panel" title="Explained by">{{template "icon" "panel-right"}}</button>{{end}}</div><div class="code-workspace" data-code-workspace><div class="code-main">{{with .Selected}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}" data-file-diff-href="{{$.DiffHref}}?file={{urlquery .Path}}"><header class="file-head">{{template "ficon" .Path}}<code>{{.Path}}</code><span class="counts">{{template "diff-counts" .}}</span></header>{{template "review-file-diff-surface" (reviewDiffSurface .Path "")}}</article>{{else}}<div class="remaining">{{.EmptyNote}}</div>{{end}}</div>{{if and .Selected .Explanations}}<aside class="related-saga" id="related-saga-panel" aria-label="Explanations for this file">{{range .Owners}}<section class="related-chapter">{{if .Chapter}}<a class="related-chapter-link" href="{{.Href}}">{{.Chapter}}</a>{{end}}<a class="related-fragment" href="{{.Href}}" data-open-fragment="{{.Anchor}}"><strong>{{.Title}}</strong></a></section>{{else}}<p>{{.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></section>{{end}}

{{define "manifest-diff-row"}}{{if eq .Kind "context"}}<div class="diff-row context"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span></span></div>{{else}}<div class="diff-row {{.Kind}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><span class="line-no">{{if .NewLine}}{{.NewLine}}{{end}}</span><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{end}}{{end}}

{{define "manifest-target"}}<details class="manifest-target" data-manifest-search="{{.Title}} {{.Chapter}}"><summary>{{template "twisty"}}{{if .Slide}}<span class="manifest-target-slide-preview" aria-hidden="true">{{template "slide-mini-media" .Slide}}</span>{{else}}{{template "icon" "book"}}{{end}}<span class="manifest-target-title"><strong>{{if .Slide}}{{.Slide.Title}}{{else}}{{.Title}}{{end}}</strong>{{if .Slide}}<small>{{if ne .Title .Slide.Title}}{{.Title}}{{if .Chapter}} · {{end}}{{end}}{{.Chapter}}</small>{{else if .Chapter}}<small>{{.Chapter}}</small>{{end}}</span><span class="manifest-file-stats">{{.AtomCount}} {{if eq .AtomCount 1}}change{{else}}changes{{end}}</span></summary><div class="manifest-target-files">{{range .Files}}{{template "manifest-target-file" .}}{{end}}<a class="manifest-open-saga" href="{{.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a></div></details>{{end}}

{{define "manifest-target-file"}}<details class="manifest-target-file"><summary>{{template "twisty"}}{{template "ficon" .Path}}<code>{{.Path}}</code><span class="manifest-file-stats">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} file {{if eq .Events 1}}event{{else}}events{{end}}{{end}}</span></summary><div class="manifest-target-file-detail">{{if .HasDiff}}{{template "manifest-diff-surface" .Path}}{{end}}<div class="manifest-target-links"><span>Linked {{if eq (len .Chunks) 1}}range{{else}}ranges{{end}}</span>{{range .Chunks}}<a href="{{.Href}}">{{.Label}}</a>{{end}}<a class="manifest-full-diff" href="{{.Href}}">Open in Code Diff {{template "icon" "arrow-right"}}</a></div></div></details>{{end}}

{{define "chapter-list"}}<div class="chapter-pages">{{range .ChildViews}}{{if eq .Kind "chapter"}}{{template "chapter" .}}{{else}}{{template "section" .}}{{end}}{{end}}</div>{{end}}

{{define "trace-links"}}<ul class="trace-links">{{range .}}<li data-trace-target="{{.Target}}">{{if .Href}}<a href="{{.Href}}">{{.Title}}</a>{{else}}<span>{{.Title}}</span>{{end}}{{if .Kind}} <small class="trace-kind">{{.Kind}}</small>{{end}}{{if .Note}} <small class="trace-note">{{.Note}}</small>{{end}}{{if .Rationale}}<p class="trace-rationale">{{.Rationale}}</p>{{end}}</li>{{end}}</ul>{{end}}

{{/* Related reviews are a footnote, never a headline: they sit at the
bottom of a record's page, below its own content, and appear in no table and no
header count. They are derived from the code the record's own chain reaches,
so there is nothing here for an author or an agent to maintain. */}}
{{define "related-reviews"}}{{if .Reviews}}<aside class="related-reviews" data-related-reviews="{{.Kind}}"><h2>Related reviews</h2><ul>{{range .Reviews}}<li data-related-review="{{.ID}}"><a href="{{.Href}}">{{.Title}}</a>{{if .Number}} <span class="related-review-pr">#{{.Number}}</span>{{end}}{{if .Merged}} <span class="related-review-state">merged</span>{{end}}</li>{{end}}</ul><p class="related-reviews-note">Derived, not authored: these reviews changed lines inside the code this {{.Kind}} explains.</p></aside>{{end}}{{end}}

{{define "persona-page"}}<section class="app-page persona-page" data-persona-page data-persona-target="{{.Target}}"><nav class="requirements-breadcrumbs" aria-label="Persona breadcrumb"><span>Personas</span><span>/</span><strong>{{.Name}}</strong></nav>
<header class="requirement-story-hero"><div><p class="app-page-kind">Persona</p><h1>{{.Name}}</h1><p class="app-lede">A persona is someone who gets value from the app, the &#34;As a &hellip;&#34; of a user story, never a tool or agent that operates it.</p>{{if .Retired}}<p class="term-state">Retired: the app no longer serves this persona.</p>{{end}}</div></header>
{{if .Description}}<section class="requirement-need"><p>{{.Description}}</p></section>{{end}}
<section class="app-page-section" data-persona-served><h2>Served by</h2>{{if .Served}}{{template "trace-links" .Served}}{{else}}<p class="term-empty">No accepted story names this persona yet. Naming it on the stories that serve it (<code>change-saga story revise --persona</code>) links the persona to the design and code those stories reach.</p>{{end}}{{if .Other}}<h3>Stories not yet accepted</h3>{{template "trace-links" .Other}}{{end}}</section>
<section class="app-page-section" data-persona-terms><h2>Terms</h2>{{if .Terms}}<ul class="term-links">{{range .Terms}}<li><a href="{{.Href}}" data-term-target="{{.Target}}">{{.Title}}</a></li>{{end}}</ul>{{else}}<p class="term-empty">No term names this persona yet.</p>{{end}}</section>
</section>{{end}}

{{/* The overview's own directory: its parts, what each one holds, and where
each one opens. A part nothing has been authored into keeps its row and states
the command that fills it, the way the sidebar's gap rows do. */}}
{{define "overview-directory"}}<section class="overview-directory" data-overview-directory><h2>What this app is made of</h2><ul class="overview-parts">{{range .}}<li class="overview-part{{if .Gap}} gap{{end}}" data-overview-part="{{.Title}}"><a class="overview-part-link" href="{{.Href}}">{{.Title}}</a><span class="overview-part-count">{{.Count}}</span><p class="overview-part-note">{{.Note}}</p></li>{{end}}</ul></section>{{end}}

{{define "design-system-page"}}<section class="app-page design-system-page" data-design-system-page><nav class="requirements-breadcrumbs" aria-label="Design system breadcrumb"><a href="/">Overview</a><span>/</span><strong>Design system</strong></nav><header class="page-heading"><h1>Design system</h1><p class="app-lede">The references and chapters the interface is built from.</p></header>{{with .DesignSystem}}{{template "overview" .}}{{if .ChildViews}}<section class="chapter-index"><h2>Chapters</h2>{{template "chapter-list" .}}</section>{{end}}{{else}}<p class="app-empty">No design system yet. Run <code>change-saga design</code> to record what the interface is built from.</p>{{end}}</section>{{end}}

{{define "feature-page"}}<section class="app-page feature-page" data-feature-page data-feature-target="{{.Target}}"><nav class="requirements-breadcrumbs" aria-label="Feature breadcrumb"><span>Features</span><span>/</span><strong>{{.Title}}</strong></nav>
<header class="requirement-story-hero"><div><p class="app-page-kind">Feature</p><h1>{{.Title}}</h1></div></header>
{{if .Description}}<section class="requirement-need"><p>{{.Description}}</p></section>{{end}}
{{with .Summary}}<dl class="feature-summary" data-feature-summary><div><dt>Stories</dt><dd>{{.Stories}}{{if .Stories}} <small>{{.Accepted}} accepted</small>{{end}}</dd></div><div><dt>Design</dt><dd>{{.StoriesWithDesign}} of {{.Stories}} <small>stories have design</small></dd></div><div><dt>Quality</dt><dd>{{.CriteriaWithTests}} of {{.Criteria}} <small>criteria have a test · {{.TestCases}} test {{if eq .TestCases 1}}case{{else}}cases{{end}}</small></dd></div><div><dt>Implementation</dt><dd>{{.Slides}} <small>{{if eq .Slides 1}}slide{{else}}slides{{end}} · {{.ItemsWithCode}} of {{.Items}} Items reference code</small></dd></div></dl>{{end}}
{{if .Report}}<section class="app-page-section feature-report">{{if .Report.FragmentViews}}{{template "overview" .Report}}{{end}}{{template "chapter-list" .Report}}</section>{{end}}
{{if .Stories}}<section class="app-page-section" id="feature-product" data-feature-stories><h2>Product</h2><ul class="trace-links feature-stories">{{range .Stories}}<li data-trace-target="{{.Target}}"><a href="{{.Href}}">{{.Title}}</a> <small class="trace-kind">{{.Lifecycle}}</small><small class="trace-note">{{if .Design}}design{{else}}no design yet{{end}} · {{.Tested}} of {{.Criteria}} criteria tested</small>{{if .Personas}}<p class="trace-rationale">Serves {{range $index, $persona := .Personas}}{{if $index}}, {{end}}<a href="{{$persona.Href}}">{{$persona.Title}}</a>{{end}}</p>{{end}}</li>{{end}}</ul></section>{{end}}
{{with .Design}}<section class="app-page-section" id="feature-design" data-feature-design><h2>Design</h2>{{if .FragmentViews}}{{template "overview" .}}{{end}}{{template "chapter-list" .}}</section>{{end}}
{{if .Tests}}<section class="app-page-section" id="feature-quality" data-feature-quality><h2>Quality</h2>{{template "trace-links" .Tests}}</section>{{end}}
{{if .Decks}}<section class="app-page-section" id="feature-implementation" data-feature-implementation><h2>Implementation</h2>{{range .Decks}}<h3>{{.Title}}</h3>{{template "trace-links" .Slides}}{{end}}</section>{{end}}
{{template "related-reviews" (relatedReviews "feature" .RelatedReviews)}}</section>{{end}}

{{define "test-case-page"}}<section class="app-page test-case-page" data-test-case-page data-test-case-target="{{.Target}}"><nav class="requirements-breadcrumbs" aria-label="Test case breadcrumb">{{with .Feature}}{{if .Href}}<a href="{{.Href}}">{{.Title}}</a><span>/</span>{{end}}{{end}}<span>Test cases</span><span>/</span><strong>{{.Title}}</strong></nav>
<header class="requirement-story-hero"><div><p class="app-page-kind">Test case</p><h1>{{.Title}}</h1></div></header>{{if .Conflict}}<div class="requirements-conflict" role="alert">{{template "icon" "alert"}}<span>This test case has more than one current revision or lifecycle state. No state is being guessed.</span></div>{{end}}
<dl class="feature-summary"><div><dt>Lifecycle</dt><dd>{{.Lifecycle}}</dd></div><div><dt>Automation</dt><dd>{{or .Automation "not stated"}}</dd></div><div><dt>Coverage</dt><dd>{{if .CoverageKinds}}{{join .CoverageKinds ", "}}{{else}}not stated{{end}}</dd></div></dl>
<section class="app-page-section" data-test-definition><h2>Definition</h2>{{if .Preconditions}}<h3>Preconditions</h3><ul>{{range .Preconditions}}<li>{{.}}</li>{{end}}</ul>{{end}}<h3>Steps</h3>{{if .Steps}}<ol class="test-steps">{{range .Steps}}<li><p>{{.Action}}</p>{{if .ExpectedResult}}<p class="trace-rationale">Expect: {{.ExpectedResult}}</p>{{end}}</li>{{end}}</ol>{{else}}<p class="term-empty">No steps recorded.</p>{{end}}{{if .ExpectedResult}}<h3>Expected result</h3><p>{{.ExpectedResult}}</p>{{end}}</section>
<section class="app-page-section" data-test-verifies><h2>Verifies</h2>{{if .Verifies}}{{template "trace-links" .Verifies}}{{else}}<p class="term-empty">This test case verifies no acceptance criterion yet. Relating it (<code>change-saga relation add --type verifies</code>) shows which criteria it tests.</p>{{end}}</section>
<section class="app-page-section term-code-list" data-test-evidence><h2>Evidence</h2>{{range .Evidence}}<h3>{{.Role}}</h3>{{range .Code}}<figure class="term-code{{if .Stale}} stale{{end}}" data-file-path="{{.Path}}" data-test-code><figcaption>{{template "ficon" .Path}}<code>{{.Location}}</code></figcaption>{{if .Note}}<p class="term-code-note" role="note">{{.Note}}</p>{{end}}<table class="term-code-lines"><tbody>{{range .Lines}}<tr{{if .Referenced}} class="referenced"{{end}}><th scope="row">{{.Number}}</th><td><code data-code>{{.Text}}</code></td></tr>{{end}}</tbody></table></figure>{{end}}{{else}}<p class="term-empty">No evidence code recorded.</p>{{end}}</section>
<section class="app-page-section" data-test-runs><h2>Runs</h2>{{if .Runs}}<ol class="test-runs">{{range .Runs}}<li class="test-run {{.Result}}{{if .Current}} current{{end}}" data-test-run="{{.ID}}"><strong>{{.Result}}</strong>{{if .Current}} <small class="trace-kind">current</small>{{end}} <small class="trace-note">at <code>{{short .Commit}}</code> · <time datetime="{{.ExecutedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.ExecutedAt.Format "2 Jan 2006, 15:04 MST"}}</time></small>{{if .Summary}}<p class="trace-rationale">{{.Summary}}</p>{{end}}{{if .Command}}<p><code>{{.Command}}</code></p>{{end}}</li>{{end}}</ol>{{else}}<p class="term-empty">No run recorded.</p>{{end}}</section>
</section>{{end}}

{{define "terms-page"}}<section class="terms-page" data-terms-page>{{if .Index}}<header class="requirements-header">
<h1>Terms and vocabulary</h1>
</header>
<p class="terms-lede">The words this project uses in its own way, what each one means here, and the code that defines it.</p>
{{template "directory" .Directory}}{{else}}{{with .Term}}<nav class="requirements-breadcrumbs" aria-label="Term breadcrumb">
<a href="/terms">Terms and vocabulary</a>
<span>/</span>
<strong>{{.Name}}</strong></nav>
<article class="term-page" data-term-target="{{.Target}}">
<header class="requirement-story-hero">
<div>
<h1>{{.Name}}</h1>{{if .Retired}}<p class="term-state">Retired: the project no longer uses this term.</p>{{end}}
</div>
</header>
<section class="term-definition">
<p>{{.Definition}}</p>
</section>{{if .Aliases}}
<section class="term-aliases">
<h2>Also called</h2>
<ul class="term-links">{{range .Aliases}}<li>{{.}}</li>{{end}}</ul>
</section>{{end}}
<section class="term-stories">
<h2>Stories</h2>{{if .Stories}}
<ul class="term-links">{{range .Stories}}<li><a href="{{.Href}}" data-story-target="{{.Target}}">{{.Title}}</a></li>{{end}}</ul>{{else}}
<p class="term-empty">No story names this term yet.</p>{{end}}
</section>{{if .Records}}
<section class="term-records">
<h2>Related</h2>
<ul class="term-links">{{range .Records}}<li>{{if .Href}}<a href="{{.Href}}">{{.Title}}</a>{{else}}{{.Title}}{{end}}</li>{{end}}</ul>
</section>{{end}}
<section class="term-code-list">
<h2>Code</h2>{{range .Code}}<figure class="term-code{{if .Stale}} stale{{end}}" data-file-path="{{.Path}}" data-term-code>
<figcaption>{{template "ficon" .Path}}<code>{{.Location}}</code></figcaption>{{if .Note}}<p class="term-code-note" role="note">{{.Note}}</p>{{end}}
<table class="term-code-lines"><tbody>{{range .Lines}}<tr{{if .Referenced}} class="referenced"{{end}}><th scope="row">{{.Number}}</th><td><code data-code>{{.Text}}</code></td></tr>{{end}}</tbody></table>
</figure>{{else}}<p class="term-empty">No code references this term yet.</p>{{end}}
</section>
</article>{{end}}{{end}}</section>{{end}}

{{define "story-context"}}<dl class="feature-summary story-context" data-story-context><div><dt>Feature</dt><dd>{{if .FeatureLink.Href}}<a href="{{.FeatureLink.Href}}">{{.FeatureLink.Title}}</a>{{else}}<small>none</small>{{end}}</dd></div><div><dt>Personas</dt><dd>{{range $index, $persona := .Personas}}{{if $index}}, {{end}}<a href="{{$persona.Href}}" data-story-persona="{{$persona.Target}}">{{$persona.Title}}</a>{{else}}<small>No persona named yet. Naming who the story serves links it to them.</small>{{end}}</dd></div><div><dt>Citations</dt><dd>{{range .Citations}}<span class="story-citation" data-story-citation>{{if .Href}}<a href="{{.Href}}" rel="noreferrer">{{.Title}}</a>{{else}}{{.Title}}{{end}}{{if .Kind}} <small>{{.Kind}}{{if not .Href}} · {{.Reference}}{{end}}</small>{{end}}</span>{{else}}<small>No citation yet.</small>{{end}}</dd></div></dl>{{end}}

{{define "trace-groups"}}{{if .Empty}}<p class="term-empty">Nothing links to this yet. Design that addresses it, slides that explain it, and test cases that verify it appear here once related (<code>change-saga relation add</code>).</p>{{else}}{{if .Design}}<h3>Design</h3>{{template "trace-links" .Design}}{{end}}{{if .Slides}}<h3>Explained by slides</h3>{{template "trace-links" .Slides}}{{end}}{{if .Tests}}<h3>Verified by test cases</h3>{{template "trace-links" .Tests}}{{end}}{{if .Related}}<h3>Related</h3>{{template "trace-links" .Related}}{{end}}{{end}}{{end}}

{{define "historical-requirement"}}<aside class="historical-requirement" data-historical-requirement role="note">
<header><span>Historical</span><h2>Retired {{.Kind}}</h2></header>
<p>This {{.Kind}} is preserved for context and is not current product intent.</p>
<p class="historical-requirement-date"><strong>Retired:</strong> <time datetime="{{.RetiredAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.RetiredAt.Format "2 Jan 2006"}}</time></p>
{{if .Reason}}<p class="historical-requirement-reason"><strong>Recorded reason:</strong> {{.Reason}}</p>{{end}}
{{if .Replacements}}<div class="historical-replacements" data-explicit-replacements><h3>Current replacement</h3>{{template "trace-links" .Replacements}}</div>{{else}}<p class="historical-no-replacement" data-no-explicit-replacement>No current replacement is explicitly linked in the Saga.</p>{{end}}
</aside>{{end}}

{{define "criterion-trace"}}{{if not .Empty}}<p class="criterion-trace" data-criterion-trace>{{if .Design}}Design: {{range $i, $l := .Design}}{{if $i}}, {{end}}<a href="{{$l.Href}}">{{$l.Title}}</a>{{end}}. {{end}}{{if .Slides}}Explained by {{range $i, $l := .Slides}}{{if $i}}, {{end}}<a href="{{$l.Href}}">{{$l.Title}}</a>{{end}}. {{end}}{{if .Tests}}Verified by {{range $i, $l := .Tests}}{{if $i}}, {{end}}<a href="{{$l.Href}}">{{$l.Title}}</a>{{end}}.{{end}}</p>{{end}}{{end}}

{{define "criterion-page"}}{{$story := .Story}}{{with .FocusedCriterion}}<nav class="requirements-breadcrumbs" aria-label="Requirement breadcrumb">
<a href="/requirements">Requirements</a>
<span>/</span>{{with $story.FeatureLink.Href}}<a href="{{.}}">{{$story.FeatureLink.Title}}</a>
<span>/</span>{{end}}<a href="{{$story.Href}}">{{$story.Title}}</a>
<span>/</span>
<strong>{{.Label}}</strong></nav>
<article class="app-page criterion-page" data-criterion-page data-requirement-target="{{.Target}}">
<header class="requirement-story-hero"><div><p class="app-page-kind">Acceptance criterion · {{.Label}}</p><h1>{{.Statement}}</h1><p class="trace-rationale">Of the story <a href="{{$story.Href}}">{{$story.Title}}</a>.</p></div></header>
{{with .Historical}}{{template "historical-requirement" .}}{{end}}
<section class="requirement-trace" data-criterion-own-trace><h2>Linked to this criterion</h2>{{template "trace-groups" .Trace}}</section>
<section class="requirement-trace" data-criterion-story-trace><h2>Through its story</h2>{{if $story.Trace.Empty}}<p class="term-empty">Nothing links to the story as a whole.</p>{{else}}{{template "trace-groups" $story.Trace}}{{end}}</section>
<section class="app-page-section"><h2>The story's other criteria</h2><ul class="trace-links">{{range $story.Criteria}}{{if not .Selected}}<li><a href="{{.Href}}">{{.Label}}</a> <span>{{.Statement}}</span></li>{{end}}{{end}}</ul></section>
{{template "related-reviews" (relatedReviews "acceptance criterion" .RelatedReviews)}}</article>{{end}}{{end}}

{{define "requirements-page"}}<section class="requirements-page" data-requirements-page>{{if .Overview}}<header class="requirements-header">
<h1>Requirements</h1>
</header>
{{range .Groups}}<section class="requirements-feature" data-requirements-feature="{{.Feature.Target}}"><header class="requirements-feature-head"><h2><a href="{{.Feature.Href}}">{{.Feature.Title}}</a></h2>{{if .Description}}<p>{{.Description}}</p>{{end}}</header><div class="requirements-story-list">{{range .Stories}}<article class="requirements-story-card{{if .Historical}} historical{{end}}" data-requirement-target="{{.Target}}">
<header>
<div>
<h2>
<a href="{{.Href}}">{{.Title}}</a>
</h2>
{{if .Historical}}<span class="requirement-history-badge">Historical · retired</span>{{end}}
</div>
</header>
<p class="requirement-story-statement">{{.Statement}}</p>
<details class="requirements-criteria-preview">
<summary>{{template "twisty"}}<span>{{len .Criteria}} {{if eq (len .Criteria) 1}}criterion{{else}}criteria{{end}}</span>
</summary>
<ol>{{range .Criteria}}<li>
<a href="{{.Href}}">
<span>{{.Label}}</span>
<strong>{{.Statement}}</strong>
</a>
</li>{{end}}</ol>
</details>
</article>{{end}}</div></section>{{else}}<div class="requirements-empty">
<strong>No stories yet.</strong>
<span>Add the first story through the requirements authoring workflow.</span>
</div>{{end}}{{else if .FocusedCriterion}}{{template "criterion-page" .}}{{else}}{{with .Story}}<nav class="requirements-breadcrumbs" aria-label="Requirement breadcrumb">
<a href="/requirements">Requirements</a>
<span>/</span>{{with .FeatureLink.Href}}<a href="{{.}}">{{$.Story.FeatureLink.Title}}</a>
<span>/</span>{{end}}
<strong>{{.Title}}</strong></nav>
<article class="requirement-story-page" data-requirement-target="{{.Target}}">
<header class="requirement-story-hero">
<div>
<p class="app-page-kind">Story · {{.Lifecycle}}</p>
<h1>{{.Title}}</h1>
</div>
</header>{{with .Historical}}{{template "historical-requirement" .}}{{end}}{{template "story-context" .}}{{if or .RevisionConflict .LifecycleConflict}}<div class="requirements-conflict" role="alert">{{template "icon" "alert"}}<span>This story has {{if .RevisionConflict}}multiple revision heads{{end}}{{if and .RevisionConflict .LifecycleConflict}} and {{end}}{{if .LifecycleConflict}}multiple lifecycle heads{{end}}. No state is being guessed.</span>
</div>{{end}}
<section class="requirement-need">
<p>{{.Statement}}</p>
</section>
<details class="requirement-story-details">
<summary>{{template "twisty"}}<span>Details</span></summary>
<div class="requirement-story-details-content">
<div class="requirement-characterization">
<dl>
<div>
<dt>Lifecycle</dt>
<dd>{{.Lifecycle}}{{if .LifecycleReason}}<small>{{.LifecycleReason}}</small>{{end}}</dd>
</div>
<div>
<dt>Priority</dt>
<dd>{{.Priority}}</dd>
</div>
<div>
<dt>Revision</dt>
<dd>
<code>{{.Revision}}</code>
</dd>
</div>
<div>
<dt>Stable identity</dt>
<dd>
<code>{{.ID}}</code>
</dd>
</div>
<div>
<dt>Created</dt>
<dd>
<time datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.CreatedAt.Format "2 Jan 2006"}}</time>
</dd>
</div>
</dl>
</div>
<div class="requirement-history-lists">
<details>
<summary>{{template "twisty"}}Revision history <span>{{len .Revisions}}</span>
</summary>
<ol>{{range .Revisions}}<li{{if .Current}} class="current"{{end}}>
<strong>{{.ID}}{{if .Current}} · current{{end}}</strong>
<code>{{.Target}}</code>
<time datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.CreatedAt.Format "2 Jan 2006, 15:04 MST"}}</time>
</li>{{end}}</ol>
</details>
<details>
<summary>{{template "twisty"}}Lifecycle history <span>{{len .LifecycleEvents}}</span>
</summary>
<ol>{{range .LifecycleEvents}}<li{{if .Current}} class="current"{{end}}>
<strong>{{.State}}{{if .Current}} · current{{end}}</strong>{{if .Reason}}<p>{{.Reason}}</p>{{end}}<code>{{.Target}}</code>
<time datetime="{{.CreatedAt.Format "2006-01-02T15:04:05Z07:00"}}">{{.CreatedAt.Format "2 Jan 2006, 15:04 MST"}}</time>
</li>{{end}}</ol>
</details>
</div>
</div>
</details>
<section class="requirement-trace" data-story-trace><h2>Linked to the whole story</h2>{{template "trace-groups" .Trace}}</section>
{{if .Terms}}<section class="requirement-terms" data-requirement-terms>
<h2>Terms</h2>
<ul class="term-links">{{range .Terms}}<li><a href="{{.Href}}" data-term-target="{{.Target}}">{{.Title}}</a></li>{{end}}</ul>
</section>{{end}}
<section class="requirement-criteria">
<header>
<h2>Acceptance criteria</h2>
</header>
<div class="requirement-criteria-list">{{range .Criteria}}<article class="requirement-criterion{{if .Selected}} selected{{end}}" id="{{.DOMID}}" data-requirement-target="{{.Target}}">
<header>
<a class="criterion-label" href="{{.Href}}">{{.Label}}</a>
</header>
<p>{{.Statement}}</p>{{template "criterion-trace" .Trace}}
</article>{{end}}</div>
</section>
{{template "related-reviews" (relatedReviews "story" .RelatedReviews)}}</article>{{end}}{{end}}</section>{{end}}
{{define "doc-tree"}}{{range .}}{{if .Slide}}<div class="doc-node doc-slide-thumbnail">{{if .Slide.Section}}<div class="slide-section-divider" data-slide-section>{{.Slide.Section}}</div>{{end}}<div class="slide-thumbnail-card" data-slide-thumbnail-card><div class="slide-thumbnail-preview" aria-hidden="true">{{if eq .Slide.MediaType "text/html"}}<iframe tabindex="-1" sandbox="allow-scripts" loading="lazy" src="{{.Slide.URL}}" title=""></iframe>{{else}}<img loading="lazy" src="{{.Slide.URL}}" alt="">{{end}}</div><span class="slide-thumbnail-caption"><span class="slide-thumbnail-title">{{.Slide.Title}}</span></span><button type="button" class="slide-thumbnail-hit" data-slide-thumbnail data-slide-target="{{.Slide.Target}}" aria-current="false" aria-label="Show slide: {{.Slide.Title}}"></button></div></div>{{else}}<div class="doc-node{{if .Deck}} doc-deck{{end}}{{if .Requirement}} doc-requirement{{end}}{{if .Group}} doc-group{{end}}{{if .Gap}} doc-gap{{end}}"><div class="doc-row {{if .Active}}current{{end}}">{{if .Children}}<button type="button" class="doc-twisty" data-doc-twisty aria-expanded="{{.Expanded}}" aria-controls="{{.NodeID}}" aria-label="Toggle {{.Title}}">{{template "twisty"}}</button>{{else}}<span class="doc-twisty placeholder" aria-hidden="true">{{template "twisty"}}</span>{{end}}{{if .Deck}}<button type="button" class="doc-link doc-deck-link" data-deck-toggle aria-expanded="{{.Expanded}}" aria-controls="{{.NodeID}}" title="{{.Title}}">{{template "icon" .Icon}}<span>{{.Title}}</span></button>{{else if .Href}}<a class="doc-link" href="{{.Href}}" title="{{.Title}}" data-report-nav{{if .Active}} aria-current="page"{{end}}>{{if .Icon}}{{template "icon" .Icon}}{{else if .IconPlaceholder}}<span class="i icon-placeholder" aria-hidden="true"></span>{{end}}{{.Title}}</a>{{else if .Children}}<button type="button" class="doc-link doc-group-link" data-doc-toggle aria-expanded="{{.Expanded}}" aria-controls="{{.NodeID}}" title="{{.Title}}">{{if .Icon}}{{template "icon" .Icon}}{{else if .IconPlaceholder}}<span class="i icon-placeholder" aria-hidden="true"></span>{{end}}<span>{{.Title}}</span></button>{{else}}<span class="doc-link doc-static" title="{{.Title}}">{{if .Icon}}{{template "icon" .Icon}}{{else if .IconPlaceholder}}<span class="i icon-placeholder" aria-hidden="true"></span>{{end}}<span>{{.Title}}</span></span>{{end}}{{if .Note}}<span class="doc-note">{{.Note}}</span>{{end}}</div>{{if .Children}}<div class="doc-children" id="{{.NodeID}}"{{if not .Expanded}} hidden{{end}}>{{template "doc-tree" .Children}}</div>{{end}}</div>{{end}}{{end}}{{end}}

{{/* The picker is a disclosure first and a combobox second. Without
JavaScript the summary opens a plain list of feature links and a way through to
the index; app.js then reveals the filter field and gives the list combobox
roles and arrow-key movement. Both states are usable; only the second is
fast. */}}


{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details data-tree-folder {{if .Expanded}}open{{end}}><summary role="treeitem" style="--depth:{{.Depth}}">{{template "twisty"}}{{template "icon" "folder"}}<span class="tree-name">{{.Name}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" data-tree-file data-tree-path="{{.File.Path}}" class="{{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" style="--depth:{{.Depth}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}" title="{{.File.Path}}">{{template "ficon" .File.Path}}<span class="tree-name">{{.Name}}</span><span class="counts">{{template "diff-counts" .File}}</span></a>{{end}}{{end}}{{end}}

{{define "permalink"}}<button class="permalink" type="button" data-copy-link="#{{.}}" aria-label="Copy link" title="Copy link">{{template "icon" "link"}}</button>{{end}}
{{define "change-reasons"}}{{if .}}<ul class="change-reasons" aria-label="Why it changed">{{range .}}<li><code>{{short .Commit}}</code> <strong>{{.Subject}}</strong> <span class="change-reason-meta">{{.Author}} · {{.Date}} · touched {{join .Touched ", "}}</span>{{if .Body}}<p>{{.Body}}</p>{{end}}{{if .Collapsed}}<ul class="change-collapsed" aria-label="Branch commits the squash kept">{{range .Collapsed}}<li><code>{{short .Commit}}</code> {{.Subject}}{{if .Body}}<p>{{.Body}}</p>{{end}}</li>{{end}}</ul>{{end}}</li>{{end}}</ul>{{end}}{{end}}
{{define "change-hunks"}}{{range .}}<div class="change-hunk"><div class="change-hunk-path">{{.Path}}{{if .Event}} · {{.Event}}{{end}}</div>{{if .Lines}}<pre>{{range .Lines}}<span class="change-line {{.Side}}">{{if eq .Side "old"}}-{{else}}+{{end}}{{printf "%5d" .Line}} {{.Content}}</span>
{{end}}</pre>{{end}}</div>{{end}}{{end}}
{{define "change-view"}}<div data-review-surface-response="change"><div class="change-wrap"><header class="change-heading"><p class="eyebrow">Comparing</p><h1>{{.Layers.Head}} against {{.Layers.Against}}</h1><p>Merge-base <code>{{short .Layers.BaseOID}}</code> · <strong>{{.Layers.Summary.Changed}}</strong> changed · <strong>{{.Layers.Summary.Affected}}</strong> affected · <strong>{{.Layers.Summary.ChangedLines}}</strong> changed lines, <strong>{{.Layers.Summary.Unreferenced}}</strong> no record references. Everything else is unchanged by this change.</p>{{range .Layers.Diagnostics}}<p class="change-note" data-change-diagnostic="{{.Code}}">{{.Message}}</p>{{end}}</header>
<section class="change-review" data-change-review aria-labelledby="change-review-heading"><h2 id="change-review-heading">Review</h2><p class="change-layer-hint">The layers below are the living documentation, shown read-only. Approval and discussion happen on the pull request's review slides.</p>{{range .Reviews}}<article class="change-review-summary" data-review-summary="{{.Report.ID}}"><header><a href="{{.Href}}"><strong>{{.Report.Title}}</strong></a>{{with .Report.PullRequest}}{{if .Number}} · #{{.Number}}{{end}}{{end}}</header><ol class="change-review-slides">{{range .Report.Slides}}<li data-review-slide-state="{{.ID}}"><span>{{.Title}}</span>{{range .Decisions}} <span class="change-review-decision {{.State}}{{if eq .Currency "out_of_date"}} out-of-date{{end}}" data-decision-state="{{.State}}" data-currency="{{.Currency}}">{{.State}}{{if eq .Currency "out_of_date"}} · out of date{{end}}</span>{{else}} <span class="change-review-decision none">no decision</span>{{end}}</li>{{end}}</ol></article>{{else}}<p class="change-empty" data-change-review-missing>This change has no review yet. Create one with <code>change-saga review create</code>.</p>{{end}}</section>
<section class="change-layer" data-change-layer="changed" aria-labelledby="change-layer-changed"><h2 id="change-layer-changed">Changed <span>{{len .Layers.Changed}}</span></h2><p class="change-layer-hint">Records this change added, revised, or retired, each with its before and after.</p>{{range .Layers.Changed}}<article class="change-record {{.Change}}" id="change-{{domID .URN}}" data-change-record="{{.URN}}" data-change="{{.Change}}"><header><span class="change-badge {{.Change}}">{{.Change}}</span><span class="change-kind">{{.Kind}}</span><a class="change-title" href="#{{domID .URN}}" data-layer-link="{{.URN}}">{{.Title}}</a>{{if .Removed}}<em class="change-removed">removed</em>{{end}}</header>{{with .Pair}}<p class="change-pair {{.Basis}}" data-change-pair="{{.Basis}}">{{if eq .Basis "ambiguous"}}Could {{if eq .Role "replaces"}}replace{{else}}be replaced by{{end}} {{join .Candidates ", "}}. Link the pair: <code>{{.Link}}</code>{{else}}{{if eq .Role "replaces"}}Replaces{{else}}Replaced by{{end}} <a href="#change-{{domID .With}}" data-change-pair-with="{{.With}}">{{index $.Titles .With}}</a> ({{.Basis}}{{if .Shared}}: both explain {{join .Shared ", "}}{{end}}){{end}}</p>{{end}}<div class="before-after">{{if .Before}}<div class="before"><h3>Before{{if .Before.State}} · {{.Before.State}}{{end}}</h3><pre>{{.Before.Text}}</pre></div>{{end}}{{if .After}}<div class="after"><h3>After{{if .After.State}} · {{.After.State}}{{end}}</h3><pre>{{.After.Text}}</pre></div>{{end}}</div>{{template "change-reasons" .Reasons}}</article>{{else}}<p class="change-empty">The change edited no records.</p>{{end}}</section>
<section class="change-layer" data-change-layer="affected" aria-labelledby="change-layer-affected"><h2 id="change-layer-affected">Affected <span>{{len .Layers.Affected}}</span></h2><p class="change-layer-hint">Records the change did not edit but invalidated: their code changed, they pin a revision that changed, or they are reached through the persona, story, design, and code chain.</p>{{range .Layers.Affected}}<article class="change-record affected" data-change-record="{{.URN}}" data-change="affected"><header><span class="change-badge affected">affected</span><span class="change-kind">{{.Kind}}</span><a class="change-title" href="#{{domID .URN}}" data-layer-link="{{.URN}}">{{.Title}}</a></header><ul class="change-causes">{{range .Because}}<li class="{{.Kind}}"><span class="change-cause-kind">{{.Kind}}</span> {{.Detail}}</li>{{end}}</ul>{{template "change-reasons" .Reasons}}</article>{{else}}<p class="change-empty">Nothing else is affected.</p>{{end}}</section>
<section class="change-layer" data-change-layer="code" aria-labelledby="change-layer-code"><h2 id="change-layer-code">Code</h2><p class="change-layer-hint">Changed lines grouped under the records that reference them.</p>{{range .Layers.Code.Groups}}<article class="change-code-group {{.Layer}}" data-change-code="{{.URN}}"><header><span class="change-kind">{{.Kind}}</span><a class="change-title" href="#{{domID .URN}}" data-layer-link="{{.URN}}">{{.Title}}</a>{{if .Layer}}<span class="change-badge {{.Layer}}">{{.Layer}}</span>{{end}}</header>{{template "change-hunks" .Hunks}}{{template "change-reasons" .Reasons}}</article>{{end}}{{if .Layers.Code.Unreferenced}}<article class="change-code-group unreferenced" data-change-code="unreferenced"><header><strong>No record references these lines</strong></header>{{template "change-hunks" .Layers.Code.Unreferenced}}</article>{{end}}{{if .Layers.Unattached}}<h3>Commits that touched no record</h3>{{template "change-reasons" .Layers.Unattached}}{{end}}</section></div></div>{{end}}
{{define "history-view"}}<div data-review-surface-response="history"><div class="activity-wrap history-wrap"><header class="activity-heading"><div><p class="eyebrow">History</p><h1>{{.History.Title}}</h1><p>{{.History.Kind}} · <code>{{.History.URN}}</code></p></div></header>{{with .History.Introduced}}<p class="history-introduced" data-history-introduced="{{.Commit}}">Introduced in <code>{{short .Commit}}</code> <strong>{{.Subject}}</strong> by {{.Author}} on {{.Date}}.</p>{{else}}<p class="history-introduced">Not committed yet.</p>{{end}}{{if .History.Replaced}}<p class="history-replaced" data-history-replaced>It replaced {{join .History.Replaced ", "}}.</p>{{end}}{{if .History.Uncommitted}}<p class="history-uncommitted">It has changes that are not committed.</p>{{end}}{{if .History.Reviews}}<section class="history-reviews" data-history-reviews><h2>Reviews that changed it</h2><ul>{{range .History.Reviews}}<li data-history-review="{{.ID}}"><a href="/reviews/{{.ID}}">{{.Title}}</a>{{with .PullRequest}}{{if .Number}} · #{{.Number}}{{end}}{{end}}{{if .Merged}} · landed as <code>{{short .Merged.Landed}}</code>{{end}} <span class="history-review-because">{{join .Because "; "}}</span></li>{{end}}</ul></section>{{end}}<ol class="history-events">{{range .History.Events}}<li class="history-event" data-history-event="{{.Commit}}"><div><code>{{short .Commit}}</code> <strong>{{.Subject}}</strong></div><div class="change-reason-meta">{{.Author}} · {{.Date}}</div>{{if .Body}}<p>{{.Body}}</p>{{end}}{{if .Collapsed}}<ul class="change-collapsed" aria-label="Branch commits the squash kept">{{range .Collapsed}}<li><code>{{short .Commit}}</code> {{.Subject}}{{if .Body}}<p>{{.Body}}</p>{{end}}</li>{{end}}</ul>{{end}}<p class="history-open">Open the comparison where it happened: <code data-history-open>{{join .Open " "}}</code></p></li>{{end}}</ol></div></div>{{end}}
{{define "history-button"}}<button type="button" class="icon-button history-button" data-open-history data-history-href="/api/history?target={{urlquery .Target}}" aria-label="History of {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="When this was introduced, what it replaced, and why it changed">{{template "icon" "clock"}}</button>{{end}}
{{define "diff-counts"}}<span class="diff-counts"><span class="add">+{{.Added}}</span><span class="del">−{{.Deleted}}</span></span>{{end}}
{{define "diff-open-button"}}{{if lt .ChangeCount 0}}<button type="button" class="icon-button diff-button loading" data-target-code-href="/api/target-code?target={{urlquery .Target}}" data-target-code-template="diffs-{{.DOMID}}" aria-label="Load linked code for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Linked code">{{template "icon" "diff"}}</button>{{else}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="{{if and .Attached (gt .Attached.LineCount 0)}}Open linked code with {{.Attached.Added}} {{if eq .Attached.Added 1}}addition{{else}}additions{{end}} and {{.Attached.Deleted}} {{if eq .Attached.Deleted 1}}deletion{{else}}deletions{{end}}{{else}}Open the {{.ChangeCount}} linked code {{if eq .ChangeCount 1}}change{{else}}changes{{end}}{{end}}" title="Linked code">{{if and .Attached (gt .Attached.LineCount 0)}}{{template "diff-counts" .Attached}}{{else}}{{template "icon" "diff"}}{{.ChangeCount}}{{end}}</button>{{end}}{{end}}
{{define "diff-control"}}{{if .ChangeCount}}{{template "diff-open-button" .}}{{else if .HasCode}}<button type="button" class="icon-button diff-button loading" data-target-code-href="/api/target-code?target={{urlquery .Target}}" data-target-code-template="diffs-{{.DOMID}}" aria-label="Load linked code for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Linked code">{{template "icon" "diff"}}</button>{{end}}{{end}}
{{define "observed-code-open-button"}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open linked code with {{.ReferenceCount}} {{if eq .ReferenceCount 1}}reference{{else}}references{{end}}" title="Linked code">{{template "icon" "implementation"}}{{.ReferenceCount}}</button>{{end}}
{{define "observed-code"}}<div class="attached-code observed-code" data-attached-title="{{.Title}}"><header class="attached-code-summary">{{template "icon" "implementation"}}<span>{{.ReferenceCount}} linked {{if eq .ReferenceCount 1}}reference{{else}}references{{end}} resolved for the viewed commit</span></header>{{template "reference-code" .Observed}}</div>{{end}}
{{define "target-code"}}<span data-target-code-response data-target-code-target="{{.Target}}" data-target-code-count="{{if .ChangeCount}}{{.ChangeCount}}{{else}}{{.ReferenceCount}}{{end}}">{{if .ChangeCount}}{{template "diff-open-button" .}}{{template "diff-template" .}}{{else if .ReferenceCount}}{{template "observed-code-open-button" .}}<template id="diffs-{{.DOMID}}">{{template "observed-code" .}}</template>{{end}}</span>{{end}}

{{define "overview"}}<section id="{{.DOMID}}"><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "history-button" .}}</div>{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .ChangeCount}}{{template "diff-template" .}}{{end}}</section>{{end}}
{{define "deck-viewer"}}<section class="deck-viewer" data-deck-viewer aria-label="Slide review"><div class="deck-viewer-stage"><header class="deck-viewer-header" aria-live="polite"><span data-slide-position></span></header>{{range $deckIndex,$deck := .ChildViews}}{{range $slideIndex,$slide := $deck.FragmentViews}}<section class="deck-viewer-slide{{if and (eq $deckIndex 0) (eq $slideIndex 0)}} active{{end}}" data-deck-slide data-deck-target="{{$deck.Target}}" data-deck-role="{{$deck.DeckRole}}" data-deck-title="{{$deck.Title}}" data-slide-title="{{$slide.Title}}" data-slide-target="{{$slide.Target}}"{{if not (and (eq $deckIndex 0) (eq $slideIndex 0))}} hidden{{end}}>{{template "fragment" $slide}}</section>{{end}}{{end}}<nav class="deck-viewer-controls" aria-label="Slide navigation"><button type="button" class="slide-step" data-slide-previous aria-label="Previous slide" title="Previous slide">‹</button><button type="button" class="slide-step" data-slide-next aria-label="Next slide" title="Next slide">›</button></nav><button type="button" class="slide-exit-presentation" data-slide-exit-presentation hidden>Exit presentation</button></div></section>{{end}}
{{define "chapter"}}<section class="section chapter" id="{{.DOMID}}" data-chapter{{if .Deferred}} data-section-href="/api/section?target={{urlquery .Target}}"{{end}}><div class="section-head chapter-head"><button type="button" class="chapter-toggle" data-chapter-toggle aria-expanded="false" aria-controls="{{.DOMID}}--body" aria-label="Open {{.Title}}">{{template "twisty"}}</button><h2><a href="#{{.DOMID}}">{{.Title}}</a></h2><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "history-button" .}}</div></div>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}<div class="chapter-body" id="{{.DOMID}}--body" data-chapter-body hidden>{{if .Deferred}}<p class="section-placeholder" data-section-placeholder>Loading this chapter…</p>{{else}}{{template "section-body" .}}{{end}}</div></section>{{end}}
{{define "section-body"}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}{{end}}
{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{template "diff-control" .}}{{template "permalink" .DOMID}}{{template "history-button" .}}</div></div>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}{{template "section-body" .}}</section>{{end}}
{{define "diff-template"}}<template id="diffs-{{.DOMID}}">{{with .Attached}}{{template "attached-code" .}}{{end}}</template>{{end}}
{{define "attached-code"}}<div class="attached-code" data-attached-title="{{.Title}}"><header class="attached-code-summary">{{template "icon" "diff"}}<span>{{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}} · {{template "diff-counts" .}}{{if .EventCount}} · {{.EventCount}} file {{if eq .EventCount 1}}event{{else}}events{{end}}{{end}}</span><span class="attached-code-scope">{{.LinkedLineCount}} linked {{if eq .LinkedLineCount 1}}line{{else}}lines{{end}} highlighted{{if .LinkedEvents}} · {{.LinkedEvents}} linked {{if eq .LinkedEvents 1}}event{{else}}events{{end}}{{end}}</span></header><div class="attached-file-list">{{range .Files}}<details class="attached-file" data-file-diff-href="/api/file-diff?file={{urlquery .Path}}&amp;target={{urlquery .Target}}" data-attached-target="{{.Target}}"><summary>{{template "twisty" }}{{template "ficon" .Path}}<span class="attached-file-main"><code>{{.Path}}</code><span class="attached-file-note {{if .MissingSummary}}missing{{end}}">{{.Summary}}</span></span><span class="attached-file-counts">{{template "diff-counts" .}}{{if .Events}} · {{.Events}} {{if eq .Events 1}}event{{else}}events{{end}}{{end}} · {{.LinkedLines}} linked</span></summary>{{template "review-file-diff-surface" (reviewDiffSurface .Path .Href)}}</details>{{end}}</div></div>{{end}}
{{define "landmark-affordance"}}<span class="landmark-affordance" data-landmark-affordance>{{template "permalink" .DOMID}}{{with .Stories}}{{if .Count}}{{template "story-control" .}}{{end}}{{end}}{{template "diff-control" .}}</span>{{end}}
{{define "fragment"}}{{if .Deferred}}{{template "fragment-descriptor" .}}{{else}}{{template "fragment-content" .}}{{end}}{{end}}
{{define "fragment-descriptor"}}<article class="fragment deferred" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" data-fragment-href="/api/fragment?target={{urlquery .Target}}" tabindex="0"><div class="fragment-head"><div class="fragment-actions">{{template "permalink" .DOMID}}{{template "history-button" .}}</div></div><div class="fragment-stage"><p class="fragment-placeholder" data-fragment-placeholder>Loading this explanation…</p></div></article>{{end}}
{{define "fragment-content"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head"><div class="fragment-actions">{{with .Stories}}{{template "story-control" .}}{{end}}{{if .ChangeCount}}{{template "diff-open-button" .}}{{end}}{{if .LandmarkViews}}<details class="landmark-menu"><summary aria-label="Jump to a marked place" title="Marked places">{{template "icon" "list"}}</summary><div class="landmark-list">{{range .LandmarkViews}}<div><a href="#{{.DOMID}}">{{.Label}}</a>{{if .ChangeCount}}{{template "diff-open-button" .}}{{end}}{{template "permalink" .DOMID}}</div>{{end}}</div></details>{{end}}{{template "permalink" .DOMID}}{{template "history-button" .}}</div></div>{{range .LandmarkViews}}<span id="{{if eq .Selector.Type "heading"}}landmark-meta-{{end}}{{.DOMID}}" class="landmark-target" data-landmark-target data-landmark-anchor="{{.DOMID}}" data-landmark-type="{{.Selector.Type}}" data-element-id="{{.Selector.ElementID}}" data-heading-id="{{.Selector.HeadingID}}" data-exact="{{.Selector.Exact}}" data-prefix="{{.Selector.Prefix}}" data-suffix="{{.Selector.Suffix}}"><template data-landmark-affordance-template>{{template "landmark-affordance" .}}</template></span>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}{{end}}<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" data-fragment-frame sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open file</a>{{end}}{{range .LandmarkViews}}{{if .Region}}<div class="landmark-hotspot" data-landmark-visual="{{.DOMID}}" data-x="{{.Region.X}}" data-y="{{.Region.Y}}" data-width="{{.Region.Width}}" data-height="{{.Region.Height}}">{{template "landmark-affordance" .}}</div>{{end}}{{end}}</div>{{if .ChangeCount}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "diff-surface-row"}}{{if eq .Kind "context"}}<div class="diff-row context{{if .Linked}} linked-evidence{{end}}" data-context-row role="group" aria-label="Unchanged line {{.NewLine}}"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event{{if .Linked}} linked-evidence{{end}}"{{with .Atom}} data-diff-ref="{{.Ref}}" data-target="{{.Target}}"{{end}}><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span></div>{{else}}{{$atom := .Atom}}<div class="diff-row {{.Kind}} {{if $atom.Selected}}selected{{end}}{{if .Linked}} linked-evidence{{end}}" data-diff-row data-side="{{.Kind}}" data-line="{{if eq .Kind "old"}}{{.OldLine}}{{else}}{{.NewLine}}{{end}}" data-path="{{.Path}}" data-diff-ref="{{$atom.Ref}}" data-target="{{$atom.Target}}" role="group" aria-label="{{if eq .Kind "old"}}Removed old line {{.OldLine}}{{else}}Added new line {{.NewLine}}{{end}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><span class="line-no">{{if .NewLine}}{{.NewLine}}{{end}}</span><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code></div>{{end}}{{end}}
{{define "file-owners"}}<div data-file-owners-response>{{if .Groups}}{{template "related-saga-groups" .Groups}}{{else}}<p>{{.RelatedEmpty}}</p>{{end}}{{if .Terms}}<section class="file-terms" data-file-terms><h3>Terms defined here</h3><ul class="term-links">{{range .Terms}}<li><a href="{{.Href}}" data-term-target="{{.Target}}" title="{{.Location}}">{{.Name}}</a></li>{{end}}</ul></section>{{end}}</div>{{end}}
`
